/* Real photos and clips of the build (window.PINBALL_MEDIA, generated by
   tools/make_pinball_media.py): the gameplay collage in the Pinball hero, and a "From the
   workshop" strip under each chapter's text (story.js asks for it via buildMediaStrip).
   Clips loop silently in place, but only while on screen - a handful of videos decoding
   off-screen would drain a phone for nothing - and never on their own for anyone who has
   asked for reduced motion. Everything opens full-screen on click (openMedia, lightbox.js). */
(() => {
  'use strict';

  const media = window.PINBALL_MEDIA || {};
  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const PLAY = '<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M2.5 1.5 8.5 5l-6 3.5z"/></svg>';

  const watcher = 'IntersectionObserver' in window && !reduceMotion
    ? new IntersectionObserver((entries) => entries.forEach((e) => {
      if (e.isIntersecting) e.target.play().catch(() => {});
      else e.target.pause();
    }), { threshold: 0.35 })
    : null;

  function card(items, i) {
    const item = items[i];
    const clip = item.kind === 'video';
    const fig = document.createElement('figure');
    fig.className = 'media-card' + (clip ? ' media-card--clip' : '');

    const open = document.createElement('button');
    open.type = 'button';
    open.className = 'media-open';
    open.setAttribute('aria-label', `${clip ? 'Play clip' : 'Open photo'}: ${item.caption}, ${item.date}`);
    if (clip) {
      const v = document.createElement('video');
      ['muted', 'loop', 'playsinline'].forEach((a) => v.setAttribute(a, '')); // attributes, not just properties: iOS autoplay reads them
      v.muted = true;
      v.preload = 'none';
      v.poster = item.poster;
      v.src = item.src;
      v.setAttribute('aria-hidden', 'true');
      open.appendChild(v);
      open.insertAdjacentHTML('beforeend', `<span class="media-play">${PLAY}</span>`);
      if (watcher) watcher.observe(v);
    } else {
      const img = document.createElement('img');
      img.src = item.thumb;
      img.alt = item.caption;
      img.loading = 'lazy';
      img.decoding = 'async';
      open.appendChild(img);
    }
    open.addEventListener('click', () => window.openMedia && window.openMedia(items, i));
    fig.appendChild(open);

    const cap = document.createElement('figcaption');
    const time = document.createElement('time');
    time.textContent = item.date;
    cap.append(time, item.caption);
    fig.appendChild(cap);
    return fig;
  }

  window.buildMediaStrip = (items) => {
    const wrap = document.createElement('div');
    wrap.className = 'workshop';
    wrap.innerHTML = '<p class="workshop-label">From the workshop</p>';
    const grid = document.createElement('div');
    grid.className = 'workshop-grid';
    items.forEach((_, i) => grid.appendChild(card(items, i)));
    wrap.appendChild(grid);
    return wrap;
  };

  // hero: the gameplay clip leads, the finished top-down photo is pinned over its corner
  const heroSlot = document.querySelector('[data-media="hero"]');
  if (heroSlot && media.hero) {
    media.hero.forEach((item, i) => {
      const c = card(media.hero, i);
      c.classList.add(i === 0 ? 'media-card--lead' : 'media-card--pin');
      c.querySelector('.media-open').style.aspectRatio = `${item.w} / ${item.h}`;
      heroSlot.appendChild(c);
    });
  }
})();
